def build():
 d=Diagram(KEY,'DGL multi-head graph attention',SOURCE,'GATConv.forward','One homogeneous GATConv(8,4,heads2), graph.is_block=False, residual=False, edge_weight=None,activation=None,get_attention=False; library graph kernels opaque.',dict(in_feats=8,out_feats=4,num_heads=2,feat_drop=.1,attn_drop=.2,negative_slope=.2,residual=False,bias=True,activation=None,edge_weight=None,get_attention=False,homogeneous=True,is_block=False,allow_zero_in_degree=True,head_axis_retained=True))
 init=d.ref('GATConv.__init__')
 d.input('x','Homogeneous node features','[N,8]');d.input('g','Supplied DGL graph topology','N nodes / E edges',kind='control');d.input('attention','Distinct owned a_l and a_r','each[1,2,4]',kind='parameter',source=init,parameters=['attn_l','attn_r'],independent_parameters=True);d.input('bias','Owned explicit bias','[8]',kind='parameter',source=init,parameter='bias')
 d.stage('projection','ONE shared homogeneous projection','[N,2,4]',0,[('drop','Feature Dropout .1','dropout','[N,8]',dict(p=.1)),('linear','Owned Linear8 -> 8 / no bias','linear','[N,8]',REQUIRED['projection.linear']),('heads','View head and feature axes','tensor','[N,2,4]',dict(same_src_dst_tensor=True))],source=[d.entry,init])
 d.node('left','Source contribution / a_l','multiply','[N,2,1]',1,**REQUIRED['left']);d.node('right','Destination contribution / a_r','multiply','[N,2,1]',1,**REQUIRED['right'])
