 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='right' if s=='g' else 'left' if r=='retained_value' else 'out',ds='right' if s=='g' else 'left' if r=='retained_value' else 'in',sp=p if s=='attention' else 'out')
 return d.build(d.entry,'[N,2,4]','GraphAttention.md',['Homogeneous forward shares a single dropped feature tensor and single fc projection for source/destination nodes. Two attention vectors attn_l/attn_r remain independent owned Parameters.','Implementation computes source and destination scalar contributions separately and ADDS them on edges before LeakyReLU; it does not materialize a concatenation or compute Transformer QK dot products.','edge_softmax normalizes incoming neighbors for each destination/head, then attention Dropout and weighted-message sum follow. DGL graph kernels remain opaque boundaries.','Selected residualFalse yields explicit bias[heads*out_feats]; no final activation, edge-weight multiplier, head mean/concat or attention tuple is introduced. Output retains [N,2,4].','allow_zero_in_degree=True suppresses the source check; this module does not add self loops automatically.'],['Do not draw a dense N*N attention matrix, reuse one vector for both endpoint contributions, or reduce the retained head axis.'])
